/* ===== LearnForge Design System ===== */
:root {
  --color-black: #000000;
  --color-accent: #E6FF32;
  --color-burgundy: #7F2A23;
  --color-indigo: #1E3A5F;
  --color-blue: #2563EB;
  --color-white: #FFFFFF;
  --color-gray-50: #F8FAFC;
  --color-gray-100: #F1F5F9;
  --color-gray-200: #E2E8F0;
  --color-gray-300: #CBD5E1;
  --color-gray-400: #94A3B8;
  --color-gray-500: #64748B;
  --color-gray-600: #475569;
  --color-gray-700: #334155;
  --color-gray-800: #1E293B;
  --color-gray-900: #0F172A;

  --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.05);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  --max-width: 1200px;
  --nav-height: 72px;
}

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background: var(--color-white);
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
ul { list-style: none; }

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  color: var(--color-black);
}

h1 { font-size: clamp(2.5rem, 5vw, 3.8rem); }
h2 { font-size: clamp(2rem, 4vw, 2.8rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.6rem); }

.section-label {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-blue);
  margin-bottom: 0.75rem;
}

.section-title {
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.1rem;
  color: var(--color-gray-500);
  max-width: 600px;
  line-height: 1.7;
}

/* ===== Layout ===== */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 80px 0;
}

.section-header {
  text-align: center;
  margin-bottom: 56px;
}

.section-header .section-subtitle {
  margin: 0 auto;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 0.2s ease;
  border: 2px solid transparent;
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-black);
  color: var(--color-white);
}
.btn-primary:hover {
  background: var(--color-gray-800);
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-black);
}
.btn-accent:hover {
  background: #D4ED2A;
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-outline {
  background: transparent;
  border-color: var(--color-gray-300);
  color: var(--color-gray-700);
}
.btn-outline:hover {
  border-color: var(--color-black);
  color: var(--color-black);
}

.btn-white {
  background: var(--color-white);
  color: var(--color-black);
}
.btn-white:hover {
  background: var(--color-gray-100);
  transform: translateY(-1px);
}

.btn-burgundy {
  background: var(--color-burgundy);
  color: var(--color-white);
}
.btn-burgundy:hover {
  background: #6A231D;
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-lg {
  padding: 16px 36px;
  font-size: 1.05rem;
  border-radius: var(--radius-lg);
}

/* ===== Navigation ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-gray-200);
  z-index: 1000;
  transition: box-shadow 0.3s ease;
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--color-black);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  color: var(--color-black);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav-links a {
  padding: 8px 16px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-gray-600);
  border-radius: var(--radius-sm);
  transition: all 0.15s ease;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--color-black);
  background: var(--color-gray-100);
}

.nav-cta {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
  background: none;
  border: none;
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-black);
  border-radius: 2px;
  transition: all 0.3s ease;
}

.nav-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav-toggle.active span:nth-child(2) { opacity: 0; }
.nav-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ===== Mobile Nav ===== */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  z-index: 999;
  padding: 24px;
  flex-direction: column;
  gap: 4px;
  overflow-y: auto;
}

.mobile-nav.active { display: flex; }

.mobile-nav a {
  display: block;
  padding: 14px 16px;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--color-gray-700);
  border-radius: var(--radius-md);
  transition: all 0.15s ease;
}

.mobile-nav a:hover {
  background: var(--color-gray-100);
  color: var(--color-black);
}

.mobile-nav .btn {
  margin-top: 16px;
  text-align: center;
}

/* ===== Hero ===== */
.hero {
  padding: calc(var(--nav-height) + 60px) 0 80px;
  background: var(--color-white);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.15) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.hero-content {
  position: relative;
  z-index: 1;
}

.hero-content .section-label {
  margin-bottom: 1rem;
}

.hero-title {
  margin-bottom: 1.25rem;
}

.hero-subtitle {
  font-size: 1.15rem;
  color: var(--color-gray-500);
  margin-bottom: 2rem;
  line-height: 1.7;
  max-width: 520px;
}

.hero-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
  z-index: 1;
}

/* ===== Hero Tabs (Home) ===== */
.hero-tabs {
  display: flex;
  gap: 0;
  margin-bottom: 24px;
  background: var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 4px;
  width: fit-content;
}

.hero-tab-btn {
  padding: 10px 24px;
  border: none;
  background: transparent;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-gray-500);
  cursor: pointer;
  border-radius: var(--radius-md);
  transition: all 0.2s ease;
  white-space: nowrap;
}

.hero-tab-btn.active {
  background: var(--color-white);
  color: var(--color-black);
  box-shadow: var(--shadow-sm);
}

.hero-preview {
  background: var(--color-gray-50);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 24px;
  min-height: 350px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s ease;
  box-shadow: var(--shadow-lg);
}

.preview-panel {
  display: none;
  width: 100%;
}

.preview-panel.active {
  display: block;
}

/* Creator preview mockup */
.preview-mockup {
  background: var(--color-white);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-md);
}

.preview-mockup-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-gray-200);
}

.preview-mockup-title {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--color-gray-600);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.preview-mockup-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}

.preview-stat {
  background: var(--color-gray-50);
  border-radius: var(--radius-sm);
  padding: 14px;
  text-align: center;
}

.preview-stat-value {
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--color-black);
}

.preview-stat-label {
  font-size: 0.7rem;
  color: var(--color-gray-400);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-top: 2px;
}

.preview-mockup-chart {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.preview-chart-bar {
  background: var(--color-gray-100);
  border-radius: var(--radius-sm);
  padding: 16px;
}

.preview-chart-bar-fill {
  height: 8px;
  background: var(--color-gray-200);
  border-radius: 4px;
  margin-top: 8px;
  overflow: hidden;
}

.preview-chart-bar-fill div {
  height: 100%;
  background: var(--color-accent);
  border-radius: 4px;
}

/* Student preview */
.student-preview {
  background: var(--color-white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-md);
}

.student-preview-header {
  padding: 16px;
  background: var(--color-black);
  color: var(--color-white);
  font-size: 0.85rem;
  font-weight: 600;
}

.student-preview-body {
  padding: 20px;
}

.student-course-card {
  display: flex;
  gap: 12px;
  padding: 12px;
  background: var(--color-gray-50);
  border-radius: var(--radius-sm);
  align-items: center;
  margin-bottom: 10px;
}

.student-course-thumb {
  width: 56px;
  height: 40px;
  background: var(--color-accent);
  border-radius: 4px;
  flex-shrink: 0;
}

.student-course-info {
  flex: 1;
}

.student-course-info .title {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--color-black);
}

.student-course-info .progress {
  font-size: 0.7rem;
  color: var(--color-gray-400);
}

/* ===== Stats Bar ===== */
.stats-bar {
  background: var(--color-black);
  padding: 40px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  text-align: center;
}

.stat-item {
  padding: 0 16px;
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 3vw, 2.6rem);
  font-weight: 800;
  color: var(--color-accent);
  line-height: 1.1;
}

.stat-label {
  font-size: 0.95rem;
  color: var(--color-gray-400);
  margin-top: 4px;
  font-weight: 500;
}

/* ===== Product Cards ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  transition: all 0.3s ease;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform 0.3s ease;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.product-card:hover::before {
  transform: scaleX(1);
}

.product-card-icon {
  width: 60px;
  height: 60px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  font-size: 1.6rem;
  background: var(--color-gray-50);
}

.product-card:nth-child(1) .product-card-icon { background: #EBF5FF; color: var(--color-blue); }
.product-card:nth-child(2) .product-card-icon { background: #FEF3C7; color: #D97706; }
.product-card:nth-child(3) .product-card-icon { background: #EDE9FE; color: #7C3AED; }
.product-card:nth-child(4) .product-card-icon { background: #FCE7F3; color: #DB2777; }

.product-card h3 {
  margin-bottom: 8px;
  font-size: 1.15rem;
}

.product-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Why Choose Us Tabs ===== */
.why-tabs {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-bottom: 40px;
  flex-wrap: wrap;
}

.why-tab-btn {
  padding: 12px 24px;
  border: 1px solid var(--color-gray-200);
  background: var(--color-white);
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-gray-600);
  border-radius: var(--radius-lg);
  cursor: pointer;
  transition: all 0.2s ease;
}

.why-tab-btn:hover {
  border-color: var(--color-gray-400);
  color: var(--color-black);
}

.why-tab-btn.active {
  background: var(--color-black);
  color: var(--color-accent);
  border-color: var(--color-black);
}

.why-tab-content {
  display: none;
}

.why-tab-content.active {
  display: block;
}

.why-feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.why-feature-card {
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all 0.3s ease;
}

.why-feature-card:hover {
  background: var(--color-white);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.why-feature-card .check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--color-accent);
  color: var(--color-black);
  font-size: 0.75rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.why-feature-card h4 {
  font-size: 0.95rem;
  margin-bottom: 6px;
  font-weight: 700;
}

.why-feature-card p {
  font-size: 0.85rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Global Scale ===== */
.global-section {
  background: var(--color-gray-50);
}

.global-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.global-image {
  position: relative;
}

.global-map {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 40px;
  box-shadow: var(--shadow-lg);
  text-align: center;
}

.global-dots {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
  max-width: 400px;
  margin: 0 auto;
}

.global-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
}

.global-dot.active {
  background: var(--color-accent);
  box-shadow: 0 0 8px rgba(230,255,50,0.5);
}

.global-highlights {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.global-highlight {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.global-highlight-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  flex-shrink: 0;
}

.global-highlight h4 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.global-highlight p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== AI Automations ===== */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.ai-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: all 0.3s ease;
}

.ai-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.ai-card-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: rgba(230,255,50,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 16px;
}

.ai-card h4 {
  margin-bottom: 8px;
  font-size: 1.05rem;
}

.ai-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Testimonials Carousel ===== */
.testimonials-section {
  background: var(--color-gray-50);
}

.testimonial-carousel {
  position: relative;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  min-width: 100%;
  padding: 0 8px;
}

.testimonial-card-inner {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 40px;
  box-shadow: var(--shadow-md);
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.15rem;
  color: var(--color-gray-700);
  line-height: 1.7;
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-tag {
  display: inline-block;
  padding: 4px 14px;
  background: var(--color-accent);
  color: var(--color-black);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 12px;
}

.testimonial-author {
  font-weight: 700;
  color: var(--color-black);
  font-size: 0.95rem;
}

.testimonial-role {
  font-size: 0.85rem;
  color: var(--color-gray-400);
  margin-top: 2px;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--color-gray-200);
  background: var(--color-white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  color: var(--color-gray-600);
  transition: all 0.2s ease;
}

.carousel-btn:hover {
  background: var(--color-black);
  color: var(--color-accent);
  border-color: var(--color-black);
}

.carousel-dots {
  display: flex;
  gap: 8px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-gray-300);
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
}

.carousel-dot.active {
  background: var(--color-black);
  width: 24px;
  border-radius: 5px;
}

/* ===== Pricing ===== */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  align-items: start;
}

.pricing-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: all 0.3s ease;
  position: relative;
}

.pricing-card.featured {
  border-color: var(--color-black);
  box-shadow: var(--shadow-xl);
  transform: scale(1.03);
}

.pricing-card.featured .pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent);
  color: var(--color-black);
  padding: 4px 18px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  white-space: nowrap;
}

.pricing-name {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.pricing-desc {
  font-size: 0.85rem;
  color: var(--color-gray-500);
  margin-bottom: 16px;
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.4rem;
  font-weight: 800;
  color: var(--color-black);
  margin-bottom: 4px;
}

.pricing-period {
  font-size: 0.85rem;
  color: var(--color-gray-400);
  margin-bottom: 20px;
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 24px;
}

.pricing-feature {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  font-size: 0.88rem;
  color: var(--color-gray-600);
  line-height: 1.5;
}

.pricing-feature .check-icon {
  color: var(--color-accent);
  font-weight: 700;
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

.pricing-enterprise {
  margin-top: 48px;
  background: var(--color-gray-900);
  border-radius: var(--radius-xl);
  padding: 40px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 32px;
  align-items: center;
}

.pricing-enterprise h3 {
  color: var(--color-white);
  margin-bottom: 8px;
}

.pricing-enterprise p {
  color: var(--color-gray-400);
  font-size: 0.9rem;
  line-height: 1.6;
}

.pricing-ent-features {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.pricing-ent-tag {
  padding: 4px 12px;
  background: rgba(255,255,255,0.1);
  color: var(--color-gray-300);
  border-radius: 20px;
  font-size: 0.78rem;
}

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 20px;
}

.integration-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  padding: 24px 16px;
  text-align: center;
  transition: all 0.2s ease;
}

.integration-card:hover {
  border-color: var(--color-gray-400);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.integration-card-icon {
  font-size: 1.5rem;
  margin-bottom: 8px;
  font-weight: 700;
}

.integration-card-name {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-gray-700);
}

/* ===== Social Proof ===== */
.social-proof {
  background: var(--color-accent);
  padding: 60px 0;
  text-align: center;
}

.social-proof h2 {
  color: var(--color-black);
  margin-bottom: 12px;
}

.social-proof p {
  font-size: 1.1rem;
  color: var(--color-gray-800);
  max-width: 600px;
  margin: 0 auto 24px;
}

/* ===== FAQ Accordion ===== */
.faq-list {
  max-width: 700px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--color-gray-200);
}

.faq-question {
  width: 100%;
  padding: 20px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-black);
  transition: color 0.15s ease;
}

.faq-question:hover {
  color: var(--color-blue);
}

.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid var(--color-gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  color: var(--color-gray-400);
  flex-shrink: 0;
  transition: all 0.3s ease;
  margin-left: 16px;
}

.faq-item.active .faq-icon {
  border-color: var(--color-black);
  color: var(--color-black);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 200px;
}

.faq-answer-inner {
  padding-bottom: 20px;
  font-size: 0.95rem;
  color: var(--color-gray-500);
  line-height: 1.7;
}

/* ===== CTA Banner ===== */
.cta-banner {
  background: var(--color-black);
  padding: 64px 0;
  text-align: center;
}

.cta-banner h2 {
  color: var(--color-white);
  margin-bottom: 12px;
}

.cta-banner p {
  color: var(--color-gray-400);
  font-size: 1.05rem;
  max-width: 550px;
  margin: 0 auto 24px;
}

.cta-banner .btn-accent {
  font-size: 1rem;
  padding: 14px 36px;
}

/* ===== Footer ===== */
.footer {
  background: var(--color-gray-900);
  padding: 64px 0 32px;
  color: var(--color-gray-400);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand p {
  font-size: 0.9rem;
  line-height: 1.6;
  margin-top: 12px;
  max-width: 280px;
}

.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--color-white);
}

.footer-col h4 {
  color: var(--color-white);
  font-size: 0.85rem;
  font-weight: 700;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 0.9rem;
  color: var(--color-gray-400);
  transition: color 0.15s ease;
}

.footer-col a:hover {
  color: var(--color-white);
}

.footer-bottom {
  border-top: 1px solid var(--color-gray-800);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.85rem;
}

/* ===== Feature Cards (Courses page) ===== */
.feature-cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.feature-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: all 0.3s ease;
}

.feature-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.feature-card-icon {
  font-size: 1.8rem;
  margin-bottom: 16px;
}

.feature-card h4 {
  margin-bottom: 8px;
  font-size: 1.05rem;
}

.feature-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Product Demo ===== */
.product-demo {
  background: var(--color-gray-50);
}

.demo-accordion {
  max-width: 800px;
  margin: 0 auto;
}

.demo-toggle {
  width: 100%;
  padding: 20px;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-black);
  transition: all 0.2s ease;
}

.demo-toggle:hover {
  box-shadow: var(--shadow-md);
}

.demo-toggle .arrow {
  transition: transform 0.3s ease;
}

.demo-toggle.active .arrow {
  transform: rotate(180deg);
}

.demo-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.demo-content.active {
  max-height: 500px;
}

.demo-inner {
  padding: 24px;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-top: none;
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
}

.demo-mockup {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 20px;
}

.demo-sidebar {
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
  padding: 16px;
}

.demo-sidebar-item {
  padding: 10px 12px;
  margin-bottom: 4px;
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--color-gray-600);
}

.demo-sidebar-item.active {
  background: var(--color-black);
  color: var(--color-accent);
}

.demo-main {
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
  padding: 20px;
}

.demo-main-block {
  background: var(--color-white);
  border-radius: var(--radius-sm);
  padding: 16px;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.demo-main-block .drag-handle {
  color: var(--color-gray-300);
  cursor: grab;
  font-size: 1.1rem;
}

.demo-main-block .block-type {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--color-gray-500);
}

/* ===== Tools Grid ===== */
.tools-section {
  background: var(--color-gray-50);
}

.tools-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.tool-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  padding: 20px 12px;
  text-align: center;
  transition: all 0.2s ease;
}

.tool-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.tool-card-icon {
  font-size: 1.3rem;
  margin-bottom: 8px;
}

.tool-card-name {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--color-gray-700);
}

.tool-category {
  text-align: center;
  margin-bottom: 32px;
}

.tool-category-title {
  display: inline-block;
  padding: 6px 18px;
  background: var(--color-accent);
  color: var(--color-black);
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ===== File Types ===== */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.file-type-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  padding: 20px;
  text-align: center;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--color-gray-700);
  transition: all 0.2s ease;
}

.file-type-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-accent);
  color: var(--color-black);
}

.file-type-icon {
  font-size: 1.5rem;
  margin-bottom: 8px;
}

/* ===== Three Steps ===== */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-accent);
  color: var(--color-black);
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}

.step-card h4 {
  margin-bottom: 8px;
}

.step-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Resources ===== */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.resource-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all 0.3s ease;
}

.resource-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
  border-color: var(--color-accent);
}

.resource-card .resource-icon {
  font-size: 1.5rem;
  margin-bottom: 12px;
}

.resource-card h4 {
  font-size: 1rem;
  margin-bottom: 8px;
}

.resource-card p {
  font-size: 0.88rem;
  color: var(--color-gray-500);
  line-height: 1.6;
  margin-bottom: 12px;
}

.resource-link {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--color-blue);
}

/* ===== Value Props ===== */
.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.value-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  border: 1px solid var(--color-gray-200);
}

.value-card-icon {
  font-size: 2rem;
  margin-bottom: 16px;
}

.value-card h4 {
  margin-bottom: 8px;
}

.value-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Membership Benefits ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.benefit-card {
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  transition: all 0.3s ease;
}

.benefit-card:hover {
  background: var(--color-white);
  box-shadow: var(--shadow-md);
}

.benefit-card .benefit-stat {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  color: var(--color-burgundy);
  line-height: 1.1;
  margin-bottom: 8px;
}

.benefit-card h4 {
  margin-bottom: 8px;
  font-size: 1rem;
}

.benefit-card p {
  font-size: 0.88rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Coaching Spotlight ===== */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.spotlight-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all 0.3s ease;
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.spotlight-card-image {
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}

.spotlight-card:nth-child(1) .spotlight-card-image {
  background: linear-gradient(135deg, #FEF3C7, #FDE68A);
}

.spotlight-card:nth-child(2) .spotlight-card-image {
  background: linear-gradient(135deg, #DBEAFE, #93C5FD);
}

.spotlight-card:nth-child(3) .spotlight-card-image {
  background: linear-gradient(135deg, #EDE9FE, #C4B5FD);
}

.spotlight-card-body {
  padding: 20px;
}

.spotlight-card-body h4 {
  font-size: 1rem;
  margin-bottom: 6px;
}

.spotlight-card-body p {
  font-size: 0.85rem;
  color: var(--color-gray-500);
  line-height: 1.5;
}

/* ===== Why Memberships ===== */
.why-memberships {
  background: var(--color-gray-50);
}

.why-mem-stat {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-black);
  margin-bottom: 16px;
}

.why-mem-stat span {
  color: var(--color-accent);
  background: var(--color-black);
  padding: 2px 12px;
  border-radius: var(--radius-sm);
}

/* ===== Management Features ===== */
.mgmt-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.mgmt-card {
  display: flex;
  gap: 20px;
  align-items: flex-start;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all 0.3s ease;
}

.mgmt-card:hover {
  box-shadow: var(--shadow-md);
}

.mgmt-card-icon {
  font-size: 1.8rem;
  flex-shrink: 0;
}

.mgmt-card h4 {
  font-size: 1rem;
  margin-bottom: 6px;
}

.mgmt-card p {
  font-size: 0.88rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Business Fit ===== */
.business-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.business-card {
  text-align: center;
  padding: 28px;
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  transition: all 0.3s ease;
}

.business-card:hover {
  background: var(--color-white);
  box-shadow: var(--shadow-md);
}

.business-card-icon {
  font-size: 2rem;
  margin-bottom: 12px;
}

.business-card h4 {
  font-size: 1rem;
  margin-bottom: 6px;
}

.business-card p {
  font-size: 0.88rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Create & Sell ===== */
.create-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.create-image-preview {
  background: var(--color-gray-50);
  border-radius: var(--radius-xl);
  padding: 32px;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-gray-200);
}

.create-preview-list {
  width: 100%;
}

.create-preview-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  background: var(--color-white);
  border-radius: var(--radius-md);
  margin-bottom: 8px;
  box-shadow: var(--shadow-sm);
}

.create-preview-item .file-icon {
  font-size: 1.3rem;
}

.create-preview-item .file-name {
  flex: 1;
  font-size: 0.9rem;
  font-weight: 500;
}

.create-preview-item .file-price {
  font-weight: 700;
  color: var(--color-black);
  font-size: 0.9rem;
}

.create-details h3 {
  margin-bottom: 16px;
}

.create-details p {
  font-size: 0.95rem;
  color: var(--color-gray-500);
  line-height: 1.7;
  margin-bottom: 20px;
}

.create-checklist {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.create-checklist li {
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 0.92rem;
  color: var(--color-gray-700);
}

.create-checklist li::before {
  content: '✓';
  color: var(--color-black);
  font-weight: 700;
}

/* ===== Animations ===== */
.fade-up {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .hero-visual {
    order: -1;
  }

  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .pricing-card.featured {
    transform: none;
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-brand {
    grid-column: 1 / -1;
  }

  .integrations-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .tools-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .global-grid {
    grid-template-columns: 1fr;
  }

  .ai-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .create-grid {
    grid-template-columns: 1fr;
  }

  .mgmt-grid {
    grid-template-columns: 1fr;
  }

  .why-feature-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-cta .btn { display: none; }
  .nav-toggle { display: flex; }
  .nav-cta { gap: 8px; }

  .products-grid {
