  font-weight: 700;
  margin-bottom: 12px;
}

.why-feature-card h4 {
  font-size: 0.95rem;
  margin-bottom: 6px;
  font-weight: 700;
}

.why-feature-card p {
  font-size: 0.85rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Global Scale ===== */
.global-section {
  background: var(--color-gray-50);
}

.global-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.global-image {
  position: relative;
}

.global-map {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 40px;
  box-shadow: var(--shadow-lg);
  text-align: center;
}

.global-dots {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
  max-width: 400px;
  margin: 0 auto;
}

.global-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
