}

.ai-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Testimonials Carousel ===== */
.testimonials-section {
  background: var(--color-gray-50);
}

.testimonial-carousel {
  position: relative;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  min-width: 100%;
  padding: 0 8px;
}

.testimonial-card-inner {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 40px;
  box-shadow: var(--shadow-md);
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.15rem;
  color: var(--color-gray-700);
  line-height: 1.7;
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-tag {
  display: inline-block;
  padding: 4px 14px;
  background: var(--color-accent);
  color: var(--color-black);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 12px;
}

.testimonial-author {
  font-weight: 700;
  color: var(--color-black);
  font-size: 0.95rem;
}

.testimonial-role {
  font-size: 0.85rem;
  color: var(--color-gray-400);
  margin-top: 2px;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--color-gray-200);
  background: var(--color-white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  color: var(--color-gray-600);
  transition: all 0.2s ease;
}

.carousel-btn:hover {
  background: var(--color-black);
  color: var(--color-accent);
  border-color: var(--color-black);
}

.carousel-dots {
  display: flex;
  gap: 8px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-gray-300);
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
}

.carousel-dot.active {
  background: var(--color-black);
  width: 24px;
  border-radius: 5px;
}

/* ===== Pricing ===== */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  align-items: start;
}

.pricing-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: all 0.3s ease;
  position: relative;
}

.pricing-card.featured {
  border-color: var(--color-black);
  box-shadow: var(--shadow-xl);
  transform: scale(1.03);
}

.pricing-card.featured .pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent);
  color: var(--color-black);
  padding: 4px 18px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  white-space: nowrap;
}

.pricing-name {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.pricing-desc {
  font-size: 0.85rem;
  color: var(--color-gray-500);
  margin-bottom: 16px;
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.4rem;
  font-weight: 800;
  color: var(--color-black);
  margin-bottom: 4px;
}

.pricing-period {
  font-size: 0.85rem;
  color: var(--color-gray-400);
  margin-bottom: 20px;
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 24px;
}

.pricing-feature {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  font-size: 0.88rem;
  color: var(--color-gray-600);
  line-height: 1.5;
}

.pricing-feature .check-icon {
  color: var(--color-accent);
  font-weight: 700;
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

.pricing-enterprise {
  margin-top: 48px;
  background: var(--color-gray-900);
  border-radius: var(--radius-xl);
  padding: 40px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 32px;
  align-items: center;
}

.pricing-enterprise h3 {
  color: var(--color-white);
  margin-bottom: 8px;
}

.pricing-enterprise p {
  color: var(--color-gray-400);
  font-size: 0.9rem;
  line-height: 1.6;
}

.pricing-ent-features {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.pricing-ent-tag {
