  background: rgba(255,255,255,0.1);
  color: var(--color-gray-300);
  border-radius: 20px;
  font-size: 0.78rem;
}

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 20px;
}

.integration-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  padding: 24px 16px;
  text-align: center;
  transition: all 0.2s ease;
}

.integration-card:hover {
  border-color: var(--color-gray-400);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.integration-card-icon {
  font-size: 1.5rem;
  margin-bottom: 8px;
  font-weight: 700;
}

.integration-card-name {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-gray-700);
}

/* ===== Social Proof ===== */
.social-proof {
  background: var(--color-accent);
  padding: 60px 0;
  text-align: center;
}

.social-proof h2 {
  color: var(--color-black);
  margin-bottom: 12px;
}

.social-proof p {
  font-size: 1.1rem;
  color: var(--color-gray-800);
  max-width: 600px;
  margin: 0 auto 24px;
}

/* ===== FAQ Accordion ===== */
.faq-list {
  max-width: 700px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--color-gray-200);
}

.faq-question {
  width: 100%;
  padding: 20px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-black);
  transition: color 0.15s ease;
}

.faq-question:hover {
  color: var(--color-blue);
}

.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid var(--color-gray-300);
