  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  color: var(--color-gray-400);
  flex-shrink: 0;
  transition: all 0.3s ease;
  margin-left: 16px;
}

.faq-item.active .faq-icon {
  border-color: var(--color-black);
  color: var(--color-black);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 200px;
}

.faq-answer-inner {
  padding-bottom: 20px;
  font-size: 0.95rem;
  color: var(--color-gray-500);
  line-height: 1.7;
}

/* ===== CTA Banner ===== */
.cta-banner {
  background: var(--color-black);
  padding: 64px 0;
  text-align: center;
}

.cta-banner h2 {
  color: var(--color-white);
  margin-bottom: 12px;
}

.cta-banner p {
  color: var(--color-gray-400);
  font-size: 1.05rem;
  max-width: 550px;
  margin: 0 auto 24px;
}

.cta-banner .btn-accent {
  font-size: 1rem;
  padding: 14px 36px;
}

/* ===== Footer ===== */
.footer {
  background: var(--color-gray-900);
  padding: 64px 0 32px;
  color: var(--color-gray-400);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand p {
  font-size: 0.9rem;
