}

.feature-card-icon {
  font-size: 1.8rem;
  margin-bottom: 16px;
}

.feature-card h4 {
  margin-bottom: 8px;
  font-size: 1.05rem;
}

.feature-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Product Demo ===== */
.product-demo {
  background: var(--color-gray-50);
}

.demo-accordion {
  max-width: 800px;
  margin: 0 auto;
}

.demo-toggle {
  width: 100%;
  padding: 20px;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-black);
