.create-details h3 {
  margin-bottom: 16px;
}

.create-details p {
  font-size: 0.95rem;
  color: var(--color-gray-500);
  line-height: 1.7;
  margin-bottom: 20px;
}

.create-checklist {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.create-checklist li {
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 0.92rem;
  color: var(--color-gray-700);
}

.create-checklist li::before {
  content: '✓';
  color: var(--color-black);
  font-weight: 700;
}

/* ===== Animations ===== */
.fade-up {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .hero-visual {
    order: -1;
  }

  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .pricing-card.featured {
    transform: none;
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-brand {
    grid-column: 1 / -1;
  }

  .integrations-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .tools-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .global-grid {
    grid-template-columns: 1fr;
  }

  .ai-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .create-grid {
    grid-template-columns: 1fr;
  }

  .mgmt-grid {
    grid-template-columns: 1fr;
  }

  .why-feature-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-cta .btn { display: none; }
  .nav-toggle { display: flex; }
  .nav-cta { gap: 8px; }

  .products-grid {
    grid-template-columns: 1fr;
    max-width: 360px;
    margin: 0 auto;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .why-tabs {
    flex-direction: column;
    align-items: stretch;
  }

  .why-feature-grid {
    grid-template-columns: 1fr;
  }

  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .tools-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .ai-grid {
    grid-template-columns: 1fr;
  }

  .feature-cards-grid {
    grid-template-columns: 1fr;
  }

  .pricing-enterprise {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .steps-grid {
    grid-template-columns: 1fr;
  }

  .resources-grid {
    grid-template-columns: 1fr;
  }

  .benefits-grid {
    grid-template-columns: 1fr;
  }

  .spotlight-grid {
    grid-template-columns: 1fr;
  }

  .value-grid {
    grid-template-columns: 1fr;
  }

  .file-types-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .business-grid {
    grid-template-columns: 1fr;
  }

  .mgmt-grid {
    grid-template-columns: 1fr;
  }

  .hero-actions {
    flex-direction: column;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .hero-tabs {
    width: 100%;
  }

  .hero-tab-btn {
    flex: 1;
    text-align: center;
    padding: 10px 12px;
  }

  .section {
    padding: 48px 0;
  }
}

@media (max-width: 480px) {
  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .tools-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .carousel-controls {
    gap: 8px;
  }
}
