}

.why-feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.why-feature-card {
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all 0.3s ease;
}

.why-feature-card:hover {
  background: var(--color-white);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.why-feature-card .check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--color-accent);
  color: var(--color-black);
  font-size: 0.75rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.why-feature-card h4 {
  font-size: 0.95rem;
  margin-bottom: 6px;
  font-weight: 700;
}

.why-feature-card p {
  font-size: 0.85rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Global Scale ===== */
.global-section {
  background: var(--color-gray-50);
}

.global-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.global-image {
  position: relative;
}

.global-map {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 40px;
  box-shadow: var(--shadow-lg);
  text-align: center;
}

.global-dots {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
  max-width: 400px;
  margin: 0 auto;
}

.global-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
}

.global-dot.active {
  background: var(--color-accent);
  box-shadow: 0 0 8px rgba(230,255,50,0.5);
}

.global-highlights {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.global-highlight {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.global-highlight-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  flex-shrink: 0;
}

.global-highlight h4 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.global-highlight p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== AI Automations ===== */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.ai-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: all 0.3s ease;
}

.ai-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.ai-card-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: rgba(230,255,50,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 16px;
}

.ai-card h4 {
  margin-bottom: 8px;
  font-size: 1.05rem;
}

.ai-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Testimonials Carousel ===== */
.testimonials-section {
  background: var(--color-gray-50);
}

.testimonial-carousel {
  position: relative;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  min-width: 100%;
  padding: 0 8px;
}

.testimonial-card-inner {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 40px;
  box-shadow: var(--shadow-md);
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.15rem;
  color: var(--color-gray-700);
  line-height: 1.7;
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-tag {
  display: inline-block;
  padding: 4px 14px;
  background: var(--color-accent);
  color: var(--color-black);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 12px;
}

.testimonial-author {
  font-weight: 700;
  color: var(--color-black);
  font-size: 0.95rem;
}

.testimonial-role {
  font-size: 0.85rem;
  color: var(--color-gray-400);
  margin-top: 2px;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--color-gray-200);
  background: var(--color-white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  color: var(--color-gray-600);
  transition: all 0.2s ease;
}

.carousel-btn:hover {
  background: var(--color-black);
  color: var(--color-accent);
  border-color: var(--color-black);
}

.carousel-dots {
  display: flex;
  gap: 8px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-gray-300);
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
}

.carousel-dot.active {
  background: var(--color-black);
  width: 24px;
  border-radius: 5px;
}

/* ===== Pricing ===== */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  align-items: start;
}

.pricing-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: all 0.3s ease;
  position: relative;
}

.pricing-card.featured {
  border-color: var(--color-black);
  box-shadow: var(--shadow-xl);
  transform: scale(1.03);
}

.pricing-card.featured .pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent);
  color: var(--color-black);
  padding: 4px 18px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  white-space: nowrap;
}

.pricing-name {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.pricing-desc {
  font-size: 0.85rem;
  color: var(--color-gray-500);
  margin-bottom: 16px;
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.4rem;
  font-weight: 800;
  color: var(--color-black);
  margin-bottom: 4px;
}

.pricing-period {
  font-size: 0.85rem;
  color: var(--color-gray-400);
  margin-bottom: 20px;
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 24px;
}

.pricing-feature {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  font-size: 0.88rem;
  color: var(--color-gray-600);
  line-height: 1.5;
}

.pricing-feature .check-icon {
  color: var(--color-accent);
  font-weight: 700;
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

.pricing-enterprise {
  margin-top: 48px;
  background: var(--color-gray-900);
  border-radius: var(--radius-xl);
  padding: 40px;
