/* ===== Social Proof ===== */
.social-proof {
  background: var(--color-accent);
  padding: 60px 0;
  text-align: center;
}

.social-proof h2 {
  color: var(--color-black);
  margin-bottom: 12px;
}

.social-proof p {
  font-size: 1.1rem;
