  max-width: 600px;
  margin: 0 auto 24px;
}

/* ===== FAQ Accordion ===== */
.faq-list {
  max-width: 700px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--color-gray-200);
}

.faq-question {
  width: 100%;
  padding: 20px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-black);
  transition: color 0.15s ease;
}

.faq-question:hover {
  color: var(--color-blue);
}

.faq-icon {
  width: 24px;
  height: 24px;
