}

.feature-card-icon {
  font-size: 1.8rem;
  margin-bottom: 16px;
}

.feature-card h4 {
  margin-bottom: 8px;
  font-size: 1.05rem;
}

.feature-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

