.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.value-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  border: 1px solid var(--color-gray-200);
}

.value-card-icon {
  font-size: 2rem;
  margin-bottom: 16px;
}

.value-card h4 {
  margin-bottom: 8px;
}

.value-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Membership Benefits ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.benefit-card {
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  transition: all 0.3s ease;
}

.benefit-card:hover {
  background: var(--color-white);
  box-shadow: var(--shadow-md);
}

.benefit-card .benefit-stat {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  color: var(--color-burgundy);
  line-height: 1.1;
  margin-bottom: 8px;
}

.benefit-card h4 {
  margin-bottom: 8px;
  font-size: 1rem;
}

.benefit-card p {
  font-size: 0.88rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Coaching Spotlight ===== */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.spotlight-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all 0.3s ease;
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.spotlight-card-image {
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}

.spotlight-card:nth-child(1) .spotlight-card-image {
  background: linear-gradient(135deg, #FEF3C7, #FDE68A);
}

.spotlight-card:nth-child(2) .spotlight-card-image {
  background: linear-gradient(135deg, #DBEAFE, #93C5FD);
}

.spotlight-card:nth-child(3) .spotlight-card-image {
  background: linear-gradient(135deg, #EDE9FE, #C4B5FD);
}

.spotlight-card-body {
  padding: 20px;
}

.spotlight-card-body h4 {
  font-size: 1rem;
  margin-bottom: 6px;
}

.spotlight-card-body p {
  font-size: 0.85rem;
  color: var(--color-gray-500);
  line-height: 1.5;
}

