.mgmt-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.mgmt-card {
  display: flex;
  gap: 20px;
  align-items: flex-start;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all 0.3s ease;
}

.mgmt-card:hover {
  box-shadow: var(--shadow-md);
}

.mgmt-card-icon {
  font-size: 1.8rem;
  flex-shrink: 0;
}

.mgmt-card h4 {
  font-size: 1rem;
  margin-bottom: 6px;
}

.mgmt-card p {
  font-size: 0.88rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Business Fit ===== */
.business-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.business-card {
  text-align: center;
  padding: 28px;
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  transition: all 0.3s ease;
}

.business-card:hover {
  background: var(--color-white);
  box-shadow: var(--shadow-md);
}

.business-card-icon {
  font-size: 2rem;
  margin-bottom: 12px;
}

.business-card h4 {
  font-size: 1rem;
  margin-bottom: 6px;
}

.business-card p {
  font-size: 0.88rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ===== Create & Sell ===== */
.create-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
