  border-radius: var(--radius-md);
  margin-bottom: 8px;
  box-shadow: var(--shadow-sm);
}

.create-preview-item .file-icon {
  font-size: 1.3rem;
}

.create-preview-item .file-name {
  flex: 1;
  font-size: 0.9rem;
  font-weight: 500;
}

.create-preview-item .file-price {
  font-weight: 700;
  color: var(--color-black);
  font-size: 0.9rem;
}

.create-details h3 {
  margin-bottom: 16px;
}

.create-details p {
  font-size: 0.95rem;
  color: var(--color-gray-500);
  line-height: 1.7;
  margin-bottom: 20px;
}

.create-checklist {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.create-checklist li {
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 0.92rem;
  color: var(--color-gray-700);
}

.create-checklist li::before {
  content: '✓';
  color: var(--color-black);
  font-weight: 700;
}

/* ===== Animations ===== */
.fade-up {
  opacity: 0;
