    grid-template-columns: 1fr;
  }

  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .tools-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .ai-grid {
    grid-template-columns: 1fr;
  }

  .feature-cards-grid {
    grid-template-columns: 1fr;
  }

  .pricing-enterprise {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .steps-grid {
    grid-template-columns: 1fr;
  }

  .resources-grid {
    grid-template-columns: 1fr;
  }

  .benefits-grid {
    grid-template-columns: 1fr;
  }

  .spotlight-grid {
    grid-template-columns: 1fr;
  }

  .value-grid {
    grid-template-columns: 1fr;
  }

  .file-types-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .business-grid {
    grid-template-columns: 1fr;
  }

  .mgmt-grid {
    grid-template-columns: 1fr;
