      dotsContainer.querySelectorAll('.carousel-dot').forEach((dot, i) => {
        dot.addEventListener('click', () => {
          current = i;
          update();
        });
      });
    }

    // Auto-rotate
    let interval = setInterval(() => {
      current = (current + 1) % total;
